fs.writeFileSync(lockPath, JSON.stringify({ pid: 'tsk-45z-branch-session', ts: Date.now() }));

const result = run(cwd, ['return', 'branch-return-lock-untouched'], { FGOS_SESSION_ID: 'tsk-45z-branch-session' });
